package com.ventas.service;
import com.ventas.dto.XmlTrialModels.*;import com.ventas.repository.*;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;import java.time.*;import java.math.BigDecimal;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service @Profile("db") public class XmlTrialService{
 private final XmlTrialRepository repo;private final XmlTrialRenderer renderer;private final BusinessTransactions tx;private final AuthStore auth;public XmlTrialService(XmlTrialRepository repo,XmlTrialRenderer renderer,BusinessTransactions tx,AuthStore auth){this.repo=repo;this.renderer=renderer;this.tx=tx;this.auth=auth;}
 private void access(Identity a,boolean sale){if(a==null||!"ADM".equals(a.rol())||a.cambioClaveObligatorio()||!a.permisos().contains("VEN.XML")||sale&&!a.permisos().contains("VEN.HISTORIAL"))throw new AuthFailure(403,"Solo administración puede acceder al laboratorio XML");}
 public Status status(Identity a){access(a,false);return new Status("LOCAL_SIN_FIRMA",false,false,false);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Preview preview(Identity a,long sale){access(a,true);return renderer.preview(find(sale,false));}
 public Preview example(Identity a,String type){access(a,false);return renderer.preview(example(type));}
 private Document find(long id,boolean lock){if(id<1)throw new AuthFailure(400,"Venta inválida");return repo.get(id,lock).orElseThrow(()->new AuthFailure(404,"Comprobante no encontrado"));}
 static Document example(String type){if(!Set.of("B","F").contains(Objects.toString(type,"")))throw new AuthFailure(400,"Selecciona boleta o factura");return new Document(0,type,type.equals("F")?"F000":"B000",1,LocalDateTime.of(2026,1,1,12,0),"EMISOR FICTICIO PARA PRUEBAS","20123456789","DIRECCION FICTICIA - SOLO PRUEBAS","CLIENTE FICTICIO PARA PRUEBAS",type.equals("F")?"RUC":null,type.equals("F")?"20987654321":null,new BigDecimal("18"),new BigDecimal("100.00"),new BigDecimal("18.00"),new BigDecimal("118.00"),"CONFIRMADA","EMITIDO","NO_INTEGRADO",List.of(new Line(1,"PRODUCTO FICTICIO DE PRUEBA","Unidad","NIU",BigDecimal.ONE,new BigDecimal("118.000000"),new BigDecimal("118.00"),new BigDecimal("100.00"),new BigDecimal("18.00"))));}
 private void fresh(Identity a,boolean sale){var user=auth.lockUser(a.id()).orElseThrow(AuthFailure::expired);var permissions=auth.permissions(a.id());if(!"ADM".equals(user.rol())||sale&&!permissions.contains("VEN.HISTORIAL"))throw new AuthFailure(403,"Los permisos cambiaron. Inicia sesión de nuevo");}
 private Download result(Document d){var preview=renderer.preview(d);if(!preview.generable())throw new AuthFailure(409,String.join(" ",preview.errores()));byte[] data=preview.xml().getBytes(StandardCharsets.UTF_8);if(data.length>2000000)throw new AuthFailure(400,"El borrador supera el tamaño permitido");try{return new Download("PRUEBA-SIN-VALIDEZ-"+d.serie()+"-"+d.numero()+".xml",data,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public Download download(Identity a,String pc,long sale){access(a,true);return tx.write(a,pc,"VEN.XML",()->{fresh(a,true);var d=find(sale,true);var result=result(d);repo.audit(a.id(),sale,d.tipo());return result;});}
 public Download downloadExample(Identity a,String pc,String type){access(a,false);var d=example(type);return tx.write(a,pc,"VEN.XML",()->{fresh(a,false);var result=result(d);repo.audit(a.id(),null,"EJEMPLO_"+type);return result;});}
}
